#include "courses.hpp"

using namespace std;

Course::Course (int i, string cn, int c, string pi, string pn, string t, string ed, int cu, int p, vector<int>mi)
{
    id = i;
    name = cn;
    capacity = c;
    professor_id = pi;
    professor_name = pn;
    time = t;
    exam_date = ed;
    class_number = cu;
    prerequisite = p;
    major_ids = mi;
}

Course* Course::create_new_course(Course* wanted_course)
{
    int id = wanted_course->id;
    string course_name = wanted_course->name;
    int capacity = wanted_course->capacity;
    string professor_id = wanted_course->professor_id;
    string professor_name = wanted_course->professor_name;
    string time = wanted_course->time;
    string exam_date = wanted_course->exam_date;
    int class_number = wanted_course->class_number;
    int prerequisite = wanted_course->prerequisite;
    vector<int> major_ids = wanted_course->major_ids;
    Course *new_lesson = new Course{id, name, capacity, professor_id, professor_name, time, exam_date, class_number, prerequisite, major_ids};

}
